import { Alert, Box, FormControlLabel, FormHelperText, Paper, Switch, Typography } from '@mui/material';
import { usePlatformHost } from '@marinoscar/platform-web/core';
import { useCallback, useEffect, useId, useState } from 'react';

import { getStoreState, setStoreSwitch, type StoreState } from './api';
import { useApiAction } from '../ui';

/**
 * The built-in store, switched on and off here (#711): never an environment variable. The deployment only provides its key
 * (SECRETS_STORE_KEY, generated by the installer); without one the switch cannot be turned on and the card says why.
 */
export function BuiltinStoreCard({ canWrite }: { canWrite: boolean }) {
  const { api } = usePlatformHost();
  const action = useApiAction('Could not change the built-in store');
  const helpId = useId();
  const [state, setState] = useState<StoreState | null>(null);
  const { setError } = action;

  const load = useCallback(() => getStoreState(api).then(setState, (e: unknown) => setError(e instanceof Error && e.message ? e.message : 'Could not load the built-in store')), [api, setError]);
  useEffect(() => {
    void load();
  }, [load]);

  const toggle = async (on: boolean) => {
    const done = await action.run('save', async () => {
      await setStoreSwitch(api, on);
      return true;
    });
    if (done) await load();
  };

  return (
    <Paper variant="outlined" component="section" aria-labelledby="store-title" sx={{ p: { xs: 2, sm: 3 } }}>
      <Typography id="store-title" variant="h6" component="h2" sx={{ mb: 1 }}>
        Built-in store
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
        Hexactra&rsquo;s own encrypted store for saved logins, for people without a Vault. When it is on, each user can choose &ldquo;Store in Hexactra&rdquo; on their Secrets page. Logins only.
      </Typography>
      {action.error && (
        <Alert severity="error" sx={{ mb: 1.5 }} onClose={action.clearError}>
          {action.error}
        </Alert>
      )}
      {state && (
        <>
          <FormControlLabel
            sx={{ m: 0, minHeight: { xs: 44, sm: 'auto' } }}
            control={<Switch checked={state.enabled} disabled={!canWrite || !state.mounted || action.busy !== null} onChange={(e) => void toggle(e.target.checked)} slotProps={{ input: { 'aria-describedby': helpId } }} />}
            label="Offer the built-in store"
          />
          <FormHelperText id={helpId} sx={{ mt: 0, ml: { xs: 0, sm: 6 } }}>
            Off by default. Turning it off keeps everyone&rsquo;s saved logins; nothing is looked up through it until it is on again. Takes effect for the next run.
          </FormHelperText>
          <Box sx={{ mt: 1.5 }}>
            {state.mounted ? (
              <Typography variant="body2" color="text.secondary" data-testid="store-key">
                Store key: configured{state.keyId ? ` (id ${state.keyId})` : ''}. Back it up apart from the database: without it the saved logins cannot be read.
              </Typography>
            ) : (
              <Alert severity="warning" data-testid="store-key">
                {state.keyConfigured
                  ? 'The store needs the credential store and notifications slices, which are off on this deployment.'
                  : 'This deployment has no store key yet. Run hexactra deploy (or init): it generates SECRETS_STORE_KEY and keeps it once set. Then this switch can be turned on.'}
              </Alert>
            )}
          </Box>
        </>
      )}
    </Paper>
  );
}
